<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview Library</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f3f5fb;
      --panel: #ffffff;
      --panel-muted: #f8faff;
      --text: #182033;
      --subtle: #5e6a85;
      --border: #d8dfef;
      --accent: #3457f6;
      --accent-strong: #2643c7;
      --danger: #c62828;
      --danger-strong: #9f1d1d;
      --shadow: 0 24px 60px rgba(24, 32, 51, 0.16);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top right, rgba(52, 87, 246, 0.14), transparent 28%),
        linear-gradient(180deg, #f7f9ff 0%, var(--bg) 100%);
      color: var(--text);
    }

    body {
      padding: 24px;
    }

    .skip-link {
      position: absolute;
      top: 16px;
      left: 16px;
      transform: translateY(-180%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      text-decoration: none;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #8cb0ff;
      outline-offset: 2px;
    }

    main {
      width: min(100%, 1100px);
      margin: 0 auto;
    }

    .shell {
      display: grid;
      gap: 28px;
      align-items: start;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.9fr);
    }

    .card {
      background: rgba(255, 255, 255, 0.88);
      border: 1px solid rgba(216, 223, 239, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .preview-card {
      overflow: hidden;
    }

    .image-wrap {
      position: relative;
      aspect-ratio: 16 / 10;
      background: linear-gradient(135deg, #d8e0ff, #eef3ff 45%, #cad7ff 100%);
    }

    .image-wrap img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .preview-body,
    .details-card {
      padding: 28px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.05;
    }

    .lede,
    .meta-item span,
    .empty-state p {
      color: var(--subtle);
      line-height: 1.6;
    }

    .meta-list {
      display: grid;
      gap: 14px;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      margin: 24px 0 0;
      padding: 0;
      list-style: none;
    }

    .meta-item {
      padding: 16px;
      background: var(--panel-muted);
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .meta-item strong {
      display: block;
      margin-bottom: 6px;
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 28px;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    dialog:focus-visible {
      outline: 3px solid #8cb0ff;
      outline-offset: 3px;
    }

    .button-secondary {
      background: var(--panel);
      border-color: var(--border);
      color: var(--text);
    }

    .button-secondary:hover {
      background: #f4f7ff;
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .button-primary {
      background: var(--accent);
      color: #fff;
    }

    .button-primary:hover {
      background: var(--accent-strong);
    }

    .details-card h2,
    .dialog-content h2 {
      margin: 0 0 12px;
      font-size: 1.3rem;
    }

    .details-grid {
      display: grid;
      gap: 14px;
      margin-top: 20px;
    }

    .detail-row {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding-bottom: 14px;
      border-bottom: 1px solid var(--border);
    }

    .detail-row:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .detail-row dt {
      color: var(--subtle);
    }

    .detail-row dd {
      margin: 0;
      font-weight: 700;
      text-align: right;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 18px;
      font-weight: 600;
    }

    .status.success {
      color: #17663d;
    }

    .status.info {
      color: var(--subtle);
    }

    .empty-state {
      display: none;
      padding: 28px;
      text-align: center;
    }

    .empty-state.visible {
      display: block;
    }

    .empty-state-icon {
      display: inline-grid;
      place-items: center;
      width: 72px;
      height: 72px;
      margin-bottom: 18px;
      border-radius: 20px;
      background: var(--panel-muted);
      color: var(--accent);
      font-size: 2rem;
    }

    dialog {
      width: min(100% - 24px, 440px);
      padding: 0;
      border: 1px solid rgba(216, 223, 239, 0.95);
      border-radius: 28px;
      box-shadow: 0 28px 80px rgba(12, 18, 34, 0.32);
    }

    dialog::backdrop {
      background: rgba(16, 24, 40, 0.55);
      backdrop-filter: blur(5px);
    }

    .dialog-content {
      padding: 28px;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 52px;
      height: 52px;
      margin-bottom: 18px;
      border-radius: 16px;
      background: #fff1f1;
      color: var(--danger);
      font-size: 1.4rem;
      font-weight: 700;
    }

    .dialog-copy {
      margin: 0;
      color: var(--subtle);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 820px) {
      .shell {
        grid-template-columns: 1fr;
      }

      .meta-list {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      body {
        padding: 16px;
      }

      .preview-body,
      .details-card,
      .dialog-content,
      .empty-state {
        padding: 20px;
      }

      .detail-row {
        flex-direction: column;
      }

      .detail-row dd {
        text-align: left;
      }

      .dialog-actions,
      .actions {
        flex-direction: column;
      }

      .dialog-actions button,
      .actions button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
        --panel-muted: Canvas;
        --text: CanvasText;
        --subtle: CanvasText;
        --border: ButtonBorder;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --danger: ButtonText;
        --danger-strong: ButtonText;
      }

      .card,
      dialog,
      .meta-item,
      .empty-state-icon,
      .dialog-icon {
        box-shadow: none;
        border-color: ButtonBorder;
      }

      button {
        border-color: ButtonBorder;
      }

      .button-primary,
      .button-danger,
      .button-secondary {
        background: ButtonFace;
        color: ButtonText;
      }

      button:focus-visible,
      dialog:focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="shell">
      <section class="card preview-card" aria-labelledby="page-title">
        <div class="image-wrap" id="image-panel">
          <img
            src="https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80"
            alt="Sunlit modern workspace with a camera, notebook, and coffee cup"
          >
        </div>

        <div class="preview-body">
          <p class="eyebrow">Library Preview</p>
          <h1 id="page-title">Campaign workspace shot</h1>
          <p class="lede">
            Review the selected asset before publishing. You can keep editing metadata,
            share the image with collaborators, or remove it from your library.
          </p>

          <ul class="meta-list" aria-label="Image metadata">
            <li class="meta-item">
              <strong>Resolution</strong>
              <span>4032 x 2520 px</span>
            </li>
            <li class="meta-item">
              <strong>Format</strong>
              <span>JPEG</span>
            </li>
            <li class="meta-item">
              <strong>Added</strong>
              <span>May 3, 2026</span>
            </li>
          </ul>

          <div class="actions">
            <button class="button-primary" type="button">Share preview</button>
            <button class="button-secondary trigger" id="open-delete-dialog" type="button">
              Delete image
            </button>
          </div>

          <p id="status-message" class="status info" aria-live="polite">
            Your image is currently stored in the library.
          </p>
        </div>

        <div class="empty-state" id="empty-state" tabindex="-1">
          <div class="empty-state-icon" aria-hidden="true">✓</div>
          <h2>Image removed</h2>
          <p>The file has been deleted from your library. You can upload a new asset at any time.</p>
        </div>
      </section>

      <aside class="card details-card" aria-labelledby="details-title">
        <p class="eyebrow">Asset details</p>
        <h2 id="details-title">Ready for review</h2>
        <p class="lede">
          This product-style preview keeps high-impact actions close to the asset while
          separating destructive actions behind a confirmation step.
        </p>

        <dl class="details-grid">
          <div class="detail-row">
            <dt>Owner</dt>
            <dd>Marketing Team</dd>
          </div>
          <div class="detail-row">
            <dt>Collection</dt>
            <dd>Spring Launch</dd>
          </div>
          <div class="detail-row">
            <dt>Visibility</dt>
            <dd>Internal</dd>
          </div>
        </dl>
      </aside>
    </div>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description" class="dialog-copy">
        This will permanently remove <strong>Campaign workspace shot</strong> from your library.
        This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="button-secondary" id="cancel-delete" type="button">Cancel</button>
        <button class="button-danger" id="confirm-delete" type="button">Delete from library</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('open-delete-dialog');
    const cancelButton = document.getElementById('cancel-delete');
    const confirmButton = document.getElementById('confirm-delete');
    const imagePanel = document.getElementById('image-panel');
    const previewBody = document.querySelector('.preview-body');
    const emptyState = document.getElementById('empty-state');
    const statusMessage = document.getElementById('status-message');

    function closeDialog() {
      dialog.close();
      trigger.focus();
    }

    trigger.addEventListener('click', () => {
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', closeDialog);

    dialog.addEventListener('click', (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedInDialog =
        bounds.top <= event.clientY &&
        event.clientY <= bounds.top + bounds.height &&
        bounds.left <= event.clientX &&
        event.clientX <= bounds.left + bounds.width;

      if (!clickedInDialog) {
        closeDialog();
      }
    });

    confirmButton.addEventListener('click', () => {
      dialog.close();
      imagePanel.hidden = true;
      previewBody.hidden = true;
      emptyState.classList.add('visible');
      statusMessage.textContent = 'The image was deleted from your library.';
      statusMessage.className = 'status success';
      emptyState.focus();
    });
  </script>
</body>
</html>
