      background:
        radial-gradient(circle at top right, rgba(52, 87, 246, 0.14), transparent 28%),
        linear-gradient(180deg, #f7f9ff 0%, var(--bg) 100%);
      color: var(--text);
    }

    body {
      padding: 24px;
    }

    .skip-link {
      position: absolute;
      top: 16px;
      left: 16px;
      transform: translateY(-180%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      text-decoration: none;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #8cb0ff;
      outline-offset: 2px;
    }

    main {
      width: min(100%, 1100px);
      margin: 0 auto;
    }

    .shell {
      display: grid;
      gap: 28px;
      align-items: start;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.9fr);
    }

    .card {
      background: rgba(255, 255, 255, 0.88);
      border: 1px solid rgba(216, 223, 239, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    .preview-card {
      overflow: hidden;
    }

    .image-wrap {
      position: relative;
      aspect-ratio: 16 / 10;
      background: linear-gradient(135deg, #d8e0ff, #eef3ff 45%, #cad7ff 100%);
    }

    .image-wrap img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .preview-body,
    .details-card {
      padding: 28px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.05;
    }

    .lede,
    .meta-item span,
    .empty-state p {
      color: var(--subtle);
      line-height: 1.6;
    }

    .meta-list {
      display: grid;
      gap: 14px;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      margin: 24px 0 0;
      padding: 0;
      list-style: none;
    }

    .meta-item {
      padding: 16px;
      background: var(--panel-muted);
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .meta-item strong {
      display: block;
      margin-bottom: 6px;
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 28px;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    dialog:focus-visible {
      outline: 3px solid #8cb0ff;
      outline-offset: 3px;
    }

    .button-secondary {
      background: var(--panel);
      border-color: var(--border);
      color: var(--text);
    }

    .button-secondary:hover {
      background: #f4f7ff;
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .button-primary {
      background: var(--accent);
      color: #fff;
    }

    .button-primary:hover {
      background: var(--accent-strong);
    }

    .details-card h2,
    .dialog-content h2 {
      margin: 0 0 12px;
      font-size: 1.3rem;
    }

    .details-grid {
      display: grid;
      gap: 14px;
      margin-top: 20px;
    }

    .detail-row {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding-bottom: 14px;
      border-bottom: 1px solid var(--border);
    }

    .detail-row:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .detail-row dt {
      color: var(--subtle);
    }

    .detail-row dd {
      margin: 0;
      font-weight: 700;
      text-align: right;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 18px;
      font-weight: 600;
    }

    .status.success {
      color: #17663d;
    }

    .status.info {
      color: var(--subtle);
    }

    .empty-state {
      display: none;
      padding: 28px;
      text-align: center;
    }

    .empty-state.visible {
      display: block;
    }

    .empty-state-icon {
      display: inline-grid;
      place-items: center;
      width: 72px;
      height: 72px;
      margin-bottom: 18px;
      border-radius: 20px;
      background: var(--panel-muted);
      color: var(--accent);
      font-size: 2rem;
    }

    dialog {
      width: min(100% - 24px, 440px);
      padding: 0;
      border: 1px solid rgba(216, 223, 239, 0.95);
      border-radius: 28px;
      box-shadow: 0 28px 80px rgba(12, 18, 34, 0.32);
    }

    dialog::backdrop {
      background: rgba(16, 24, 40, 0.55);
      backdrop-filter: blur(5px);
    }

    .dialog-content {
      padding: 28px;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 52px;
      height: 52px;
      margin-bottom: 18px;
      border-radius: 16px;
      background: #fff1f1;
      color: var(--danger);
      font-size: 1.4rem;
      font-weight: 700;
    }

    .dialog-copy {
      margin: 0;
      color: var(--subtle);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 820px) {
      .shell {
        grid-template-columns: 1fr;
      }

      .meta-list {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      body {
        padding: 16px;
      }

      .preview-body,
      .details-card,
      .dialog-content,
      .empty-state {
        padding: 20px;
      }

      .detail-row {
        flex-direction: column;
      }

      .detail-row dd {
        text-align: left;
      }

      .dialog-actions,
      .actions {
        flex-direction: column;
      }

      .dialog-actions button,
      .actions button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
