      dialog,
      .meta-item,
      .empty-state-icon,
      .dialog-icon {
        box-shadow: none;
        border-color: ButtonBorder;
      }

      button {
        border-color: ButtonBorder;
      }

      .button-primary,
      .button-danger,
      .button-secondary {
        background: ButtonFace;
        color: ButtonText;
      }

      button:focus-visible,
      dialog:focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }
    }
  </style>
