      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    dialog:focus-visible {
      outline: 3px solid #8cb0ff;
      outline-offset: 3px;
    }

    .button-secondary {
