    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .button-primary {
      background: var(--accent);
      color: #fff;
    }

    .button-primary:hover {
      background: var(--accent-strong);
    }

    .details-card h2,
    .dialog-content h2 {
      margin: 0 0 12px;
      font-size: 1.3rem;
    }

    .details-grid {
      display: grid;
      gap: 14px;
      margin-top: 20px;
    }

    .detail-row {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding-bottom: 14px;
      border-bottom: 1px solid var(--border);
    }

    .detail-row:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .detail-row dt {
      color: var(--subtle);
    }

    .detail-row dd {
      margin: 0;
      font-weight: 700;
      text-align: right;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 18px;
      font-weight: 600;
    }

    .status.success {
      color: #17663d;
    }

    .status.info {
      color: var(--subtle);
    }

    .empty-state {
      display: none;
      padding: 28px;
      text-align: center;
    }

    .empty-state.visible {
      display: block;
    }

    .empty-state-icon {
      display: inline-grid;
      place-items: center;
      width: 72px;
      height: 72px;
      margin-bottom: 18px;
      border-radius: 20px;
      background: var(--panel-muted);
      color: var(--accent);
      font-size: 2rem;
    }

    dialog {
      width: min(100% - 24px, 440px);
      padding: 0;
      border: 1px solid rgba(216, 223, 239, 0.95);
      border-radius: 28px;
      box-shadow: 0 28px 80px rgba(12, 18, 34, 0.32);
    }

    dialog::backdrop {
      background: rgba(16, 24, 40, 0.55);
      backdrop-filter: blur(5px);
    }

    .dialog-content {
      padding: 28px;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 52px;
      height: 52px;
      margin-bottom: 18px;
      border-radius: 16px;
      background: #fff1f1;
      color: var(--danger);
      font-size: 1.4rem;
      font-weight: 700;
    }

    .dialog-copy {
      margin: 0;
      color: var(--subtle);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 24px;
    }

    @media (max-width: 820px) {
      .shell {
        grid-template-columns: 1fr;
      }

      .meta-list {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      body {
        padding: 16px;
      }

      .preview-body,
      .details-card,
      .dialog-content,
      .empty-state {
        padding: 20px;
      }

      .detail-row {
        flex-direction: column;
      }

      .detail-row dd {
        text-align: left;
      }

      .dialog-actions,
