        --border: ButtonBorder;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --danger: ButtonText;
        --danger-strong: ButtonText;
      }

      .card,
      dialog,
      .meta-item,
      .empty-state-icon,
      .dialog-icon {
        box-shadow: none;
        border-color: ButtonBorder;
      }

      button {
        border-color: ButtonBorder;
      }

      .button-primary,
      .button-danger,
      .button-secondary {
        background: ButtonFace;
        color: ButtonText;
      }

      button:focus-visible,
      dialog:focus-visible,
      .skip-link:focus {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="shell">
      <section class="card preview-card" aria-labelledby="page-title">
        <div class="image-wrap" id="image-panel">
          <img
            src="https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80"
            alt="Sunlit modern workspace with a camera, notebook, and coffee cup"
          >
        </div>

        <div class="preview-body">
          <p class="eyebrow">Library Preview</p>
          <h1 id="page-title">Campaign workspace shot</h1>
          <p class="lede">
            Review the selected asset before publishing. You can keep editing metadata,
            share the image with collaborators, or remove it from your library.
          </p>

          <ul class="meta-list" aria-label="Image metadata">
            <li class="meta-item">
              <strong>Resolution</strong>
              <span>4032 x 2520 px</span>
            </li>
            <li class="meta-item">
              <strong>Format</strong>
              <span>JPEG</span>
            </li>
            <li class="meta-item">
              <strong>Added</strong>
              <span>May 3, 2026</span>
            </li>
          </ul>

          <div class="actions">
            <button class="button-primary" type="button">Share preview</button>
            <button class="button-secondary trigger" id="open-delete-dialog" type="button">
              Delete image
            </button>
          </div>

        </div>

        <div class="empty-state" id="empty-state" tabindex="-1">
          <div class="empty-state-icon" aria-hidden="true">✓</div>
          <h2>Image removed</h2>
          <p>The file has been deleted from your library. You can upload a new asset at any time.</p>
        </div>

        <p id="status-message" class="status info" aria-live="polite">
          Your image is currently stored in the library.
        </p>
      </section>

      <aside class="card details-card" aria-labelledby="details-title">
        <p class="eyebrow">Asset details</p>
        <h2 id="details-title">Ready for review</h2>
        <p class="lede">
          This product-style preview keeps high-impact actions close to the asset while
          separating destructive actions behind a confirmation step.
        </p>

        <dl class="details-grid">
          <div class="detail-row">
            <dt>Owner</dt>
            <dd>Marketing Team</dd>
          </div>
          <div class="detail-row">
            <dt>Collection</dt>
            <dd>Spring Launch</dd>
          </div>
          <div class="detail-row">
            <dt>Visibility</dt>
            <dd>Internal</dd>
          </div>
        </dl>
      </aside>
    </div>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description" class="dialog-copy">
        This will permanently remove <strong>Campaign workspace shot</strong> from your library.
        This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="button-secondary" id="cancel-delete" type="button">Cancel</button>
        <button class="button-danger" id="confirm-delete" type="button">Delete from library</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('open-delete-dialog');
    const cancelButton = document.getElementById('cancel-delete');
    const confirmButton = document.getElementById('confirm-delete');
    const imagePanel = document.getElementById('image-panel');
    const previewBody = document.querySelector('.preview-body');
    const emptyState = document.getElementById('empty-state');
    const statusMessage = document.getElementById('status-message');
    let deleteConfirmed = false;

    function closeDialog() {
      dialog.close();
    }

    trigger.addEventListener('click', () => {
      deleteConfirmed = false;
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', closeDialog);

    dialog.addEventListener('close', () => {
      if (!deleteConfirmed) {
        trigger.focus();
      }
    });

    dialog.addEventListener('click', (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedInDialog =
        bounds.top <= event.clientY &&
        event.clientY <= bounds.top + bounds.height &&
        bounds.left <= event.clientX &&
        event.clientX <= bounds.left + bounds.width;

      if (!clickedInDialog) {
        closeDialog();
      }
    });

    confirmButton.addEventListener('click', () => {
      deleteConfirmed = true;
      dialog.close();
      imagePanel.hidden = true;
      previewBody.hidden = true;
      emptyState.classList.add('visible');
      statusMessage.textContent = 'The image was deleted from your library.';
      statusMessage.className = 'status success';
      emptyState.focus();
    });
  </script>
</body>
</html>
