        This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="button-secondary" id="cancel-delete" type="button">Cancel</button>
        <button class="button-danger" id="confirm-delete" type="button">Delete from library</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.getElementById('open-delete-dialog');
    const cancelButton = document.getElementById('cancel-delete');
    const confirmButton = document.getElementById('confirm-delete');
    const imagePanel = document.getElementById('image-panel');
    const previewBody = document.querySelector('.preview-body');
    const emptyState = document.getElementById('empty-state');
    const statusMessage = document.getElementById('status-message');
    let deleteConfirmed = false;

    function closeDialog() {
      dialog.close();
    }

    trigger.addEventListener('click', () => {
      deleteConfirmed = false;
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', closeDialog);

    dialog.addEventListener('close', () => {
      if (!deleteConfirmed) {
        trigger.focus();
      }
    });

    dialog.addEventListener('click', (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedInDialog =
        bounds.top <= event.clientY &&
        event.clientY <= bounds.top + bounds.height &&
        bounds.left <= event.clientX &&
        event.clientX <= bounds.left + bounds.width;

      if (!clickedInDialog) {
        closeDialog();
      }
    });

    confirmButton.addEventListener('click', () => {
      deleteConfirmed = true;
      dialog.close();
      imagePanel.hidden = true;
      previewBody.hidden = true;
      emptyState.classList.add('visible');
      statusMessage.textContent = 'The image was deleted from your library.';
      statusMessage.className = 'status success';
      emptyState.focus();
    });
  </script>
